return {["fb26_01"]={["dsc"]=[[这好像是一家相对殷实的小康人家，屋内铺着青砖，摆着一套红木桌椅。墙上挂着几幅山水画，主人不在家里。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb26_01]],["item1"]=[[fb26item100]],["item2"]=[[fb26item101]],["item3"]=[[fb26item102]],["item4"]=[[lylitem1]],["name"]=[[民居]],["permission"]=2,["rightDown"]=[[fb26_03]],["stepMusic"]=[[jiaobu]]},["fb26_02"]={["down"]=[[fb26_03]],["dsc"]=[[这里是村长的家，堂屋里堆放着一些锄头、镰刀之类的农耕用具，有一些是村中村民家里坏了，来央求村长给修的。屋檐前吊着数十串鲜红的辣椒，还有一些风干的野味。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb26_02]],["name"]=[[村长家]],["permission"]=2,["role1"]=[[fb26r02_2]],["stepMusic"]=[[jiaobu]]},["fb26_03"]={["dsc"]=[[这里是村庄中心的晒谷场，地方不大，不过村里也就五、六户人家，种的谷子也够晒了。现在正是收获的季节，谷场中堆满了谷子。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_03]],["item1"]=[[fb26item8]],["item2"]=[[fb26item8]],["item3"]=[[fb26item8]],["leftDown"]=[[fb26_04]],["leftUp"]=[[fb26_01]],["name"]=[[晒谷场]],["permission"]=2,["rightDown"]=[[fb26_05]],["role1"]=[[fb26r03_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_02]]},["fb26_04"]={["dsc"]=[[这间屋子你一进来就看见屋角大袋小袋地堆满了粮食，看来今年的收成确实不错。屋内坐着一位村民，正笑嘻嘻地看着自己的积粮，也许正在盘算这个冬天又不愁了。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb26_04]],["name"]=[[民居]],["permission"]=2,["rightUp"]=[[fb26_03]],["role1"]=[[fb26r04_1]],["role2"]=[[fb26r04_2]],["stepMusic"]=[[jiaobu]]},["fb26_05"]={["down"]=[[fb26_06]],["dsc"]=[[这是一片小村庄，隐藏在一个小山坳里。这里的居民们都很少到城里去，虽然离武功镇不过是五、六里的山路，他们宁愿秉承着男耕女织、日出而作日落而歇的老传统。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_05]],["item1"]=[[fb26item15]],["item2"]=[[fb26item107]],["item3"]=[[fb26item108]],["leftUp"]=[[fb26_03]],["name"]=[[小村庄]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb26_06"]={["dsc"]=[[从汉中西门出来，路势变急了，这是一条用石块铺成的山路。路两旁光秃秃的，没有什么树木，全是一块块的大石头。这条路好像通往前面的终南山上。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_06]],["leftDown"]=[[fb26_13]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb26_07]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_05]]},["fb26_07"]={["dsc"]=[[往东一直走便是终南山了。]],["fightBackground"]=[[山外]],["id"]=[[fb26_07]],["item1"]=[[bfitem2]],["left"]=[[fb26_06]],["name"]=[[终南山路]],["permission"]=2,["right"]=[[fb26_33]],["rightUp"]=[[fb26_34]],["stepMusic"]=[[jiaobu]]},["fb26_08"]={["down"]=[[fb26_11]],["dsc"]=[[这家酒楼是武功镇方圆百里内的唯一一家，不过连名字都没有。楼下布置简易，顾客多是匆匆的行人，买点包子、鸡腿、米酒就赶路去了。楼上是雅座。]],["id"]=[[fb26_08]],["item1"]=[[fb26r08_101]],["item2"]=[[fb26r08_102]],["name"]=[[酒楼]],["permission"]=2,["role1"]=[[fb26r08_1]],["role2"]=[[fb26r08_2]],["role3"]=[[fb26r08_3]],["role4"]=[[fb26r08_100]],["stepMusic"]=[[jiaobu]]},["fb26_09"]={["down"]=[[fb26_14]],["dsc"]=[[这是一家用茅草搭的房屋，家徒四壁，屋角的米缸是空的，厨房内的水缸也是空的。几个缺胳膊少腿的桌椅靠墙立着。看来主人已经把所有能值钱的东西全都变卖了。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb26_09]],["item1"]=[[fb26item9]],["name"]=[[民居]],["permission"]=2,["role1"]=[[fb26r09_1]],["stepMusic"]=[[jiaobu]]},["fb26_10"]={["dsc"]=[[这是一所乡间民居，桌椅都很旧了，而且看得出来是自己敲敲打打给拼补下来的，不过擦拭得很干净。墙壁上斜倚着一支猎叉，也许这家的主人还是个捕猎高手。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb26_10]],["item1"]=[[fb26item9]],["item2"]=[[fb26item10]],["name"]=[[民居]],["permission"]=2,["right"]=[[fb26_11]],["stepMusic"]=[[jiaobu]]},["fb26_11"]={["down"]=[[fb26_15]],["dsc"]=[[北街是汉中镇最繁华的街道，每逢初一十五，还要在这里举行些庙会之类的聚会。街北面是一家酒楼，楼前挂着一条蓝幅，上面写了个大大的“酒”字。西面是一户人家。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_11]],["left"]=[[fb26_10]],["name"]=[[北街]],["permission"]=2,["role1"]=[[fb26r11_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_08]]},["fb26_12"]={["down"]=[[fb26_16]],["dsc"]=[[这是一家价钱低廉的客栈，生意非常兴隆。店小二里里外外忙得团团转，接待着南腔北调的客人。客店的主人从不露面，他究竟是谁，有各种各样的猜测。]],["id"]=[[fb26_12]],["name"]=[[客店]],["permission"]=2,["role1"]=[[fb26r12_1]],["stepMusic"]=[[jiaobu]]},["fb26_13"]={["dsc"]=[[这里是汉中镇的西门，眼前城墙高耸。城门上题着“西门”两个大字，门口站着一些官兵，正手持兵刃盘问着来往的行人们。从这里折而向北，就是终南山脚了。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_13]],["name"]=[[西门]],["permission"]=2,["right"]=[[fb26_14]],["rightUp"]=[[fb26_06]],["stepMusic"]=[[jiaobu]]},["fb26_14"]={["down"]=[[fb26_19]],["dsc"]=[[汉中镇的西面是贫苦百姓的聚居区，西街比起其他几条街道来也显得破朽杂乱得多。北面是一户低矮的茅屋，西面是汉中的西门。从这里往东走就到武功镇的中心了。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_14]],["left"]=[[fb26_13]],["name"]=[[西街]],["permission"]=2,["right"]=[[fb26_15]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_09]]},["fb26_15"]={["down"]=[[fb26_20]],["dsc"]=[[这里是武功镇镇的中心广场，武功镇只有四条大街-分别是东街，西街，南街和北街，都在这里汇合。走到这里，路上的行人多了些，见了你都和和气气地拱手为礼。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_15]],["item1"]=[[fb26item104]],["left"]=[[fb26_14]],["name"]=[[中心广场]],["permission"]=2,["right"]=[[fb26_16]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_11]]},["fb26_16"]={["down"]=[[fb26_21]],["dsc"]=[[这里是武功镇的东街，往东走就是汉中东门了。汉中镇是个小城镇，不算繁华，街上的行人也很稀少。北面是一家客栈，从这里往西走，就是汉中镇的中心了。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_16]],["item1"]=[[fb26item4]],["left"]=[[fb26_15]],["name"]=[[东街]],["permission"]=1,["right"]=[[fb26_17]],["role1"]=[[fb26r16_1]],["role2"]=[[fb26r16_2]],["role3"]=[[fb26r16_3]],["role4"]=[[fb26r16_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_12]]},["fb26_17"]={["dsc"]=[[这里是汉中镇的东门，眼前城墙高耸，墙上的箭垛里好像还有人走来走去。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_17]],["item1"]=[[fb26item3]],["item2"]=[[fb26item7]],["left"]=[[fb26_16]],["name"]=[[东门]],["permission"]=1,["right"]=[[fb26_18]],["role1"]=[[fb26r17_1]],["role2"]=[[fb26r17_2]],["stepMusic"]=[[jiaobu]]},["fb26_18"]={["dsc"]=[[这是一条官府修建的大道，西面隐约可以看见武功镇的东门。远处好像可以看见巍峨的城墙。往东是通往中原的路。]],["fightBackground"]=[[山内]],["id"]=[[fb26_18]],["item1"]=[[fb26item106]],["left"]=[[fb26_17]],["name"]=[[扬州官道]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb26_19"]={["dsc"]=[[这座庙宇原本是武功镇中的土地庙，不过因为很久没有修缮过，已经破烂不堪。土地爷的金身也只剩下了半截，供桌只剩下了三条腿，窗框也已经残破不堪了。]],["id"]=[[fb26_19]],["item1"]=[[fb26item11]],["item2"]=[[fb26item103]],["name"]=[[土地庙]],["permission"]=2,["role1"]=[[fb26r19_102]],["role2"]=[[fb26r19_103]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_14]]},["fb26_20"]={["dsc"]=[[这里是汉中的南街，说是街，不过是一条小胡同而已。路上一个人也没有。街的尽头有一扇小门。从这里往北，就是武功镇的中心了。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb26_20]],["name"]=[[南街]],["permission"]=2,["rightDown"]=[[fb26_22]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_15]]},["fb26_21"]={["down"]=[[fb26_23]],["dsc"]=[[这里是汉中镇上首富李员外家的大门，门上挂着一块大横匾，上面写着“李府”两个大字。]],["id"]=[[fb26_21]],["name"]=[[富家大门]],["permission"]=1,["role1"]=[[fb26r21_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_16]]},["fb26_22"]={["dsc"]=[[这里是一道小门，可能是由于怕进出不方便而修建的出了门就是汉中镇的南街了，进门后是富家的小院。]],["id"]=[[fb26_22]],["leftUp"]=[[fb26_20]],["name"]=[[富家侧门]],["permission"]=2,["right"]=[[fb26_23]],["stepMusic"]=[[jiaobu]]},["fb26_23"]={["down"]=[[fb26_26]],["dsc"]=[[这是进门后的一个小院落。西面是一道侧门，北面是大门，南面就是大堂了。]],["id"]=[[fb26_23]],["item1"]=[[fb26item5]],["left"]=[[fb26_22]],["name"]=[[富家小院]],["permission"]=1,["right"]=[[fb26_24]],["role1"]=[[fb26r23_1]],["role2"]=[[fb26r23_2]],["role3"]=[[fb26r23_3]],["role4"]=[[fb26r23_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_21]]},["fb26_24"]={["down"]=[[fb26_27]],["dsc"]=[[这里是这户人家喝酒赏月的所在，一个小亭子建造在厅的中央，四周围绕着一些葡萄藤。一阵微风吹过，空气中似乎有隐隐的花香飘来，中人欲醉。]],["id"]=[[fb26_24]],["item1"]=[[bfitem1]],["left"]=[[fb26_23]],["name"]=[[花厅]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb26_25"]={["dsc"]=[[这里是李员外家的账房。屋内青砖铺地，进门处横摆着一张桌子，一个管家正坐在桌后，小眼睛不住地跟着你转，好像又在打什么坏主意。]],["id"]=[[fb26_25]],["name"]=[[账房]],["permission"]=2,["right"]=[[fb26_26]],["role1"]=[[fb26r25_100]],["role2"]=[[fb26r25_101]],["stepMusic"]=[[jiaobu]]},["fb26_26"]={["down"]=[[fb26_28]],["dsc"]=[[这里是李员外家的大堂，堂梁上挂着一块匾。堂内摆放着一些八仙桌和椅子，堂壁上梅兰竹菊的竹帘被挂成了兰竹菊梅，看来这家也不过是附庸风雅的暴发户而已。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb26_26]],["item1"]=[[fb26item6]],["left"]=[[fb26_25]],["name"]=[[富家大堂]],["permission"]=1,["right"]=[[fb26_27]],["role1"]=[[fb26r26_1]],["role2"]=[[fb26r26_2]],["role3"]=[[fb26r26_3]],["role4"]=[[fb26r26_4b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_23]]},["fb26_27"]={["dsc"]=[[这是正堂旁边的一间小厅，本来是用作书房的，只是李员外家实在找不出多少书来装点门面，所以就整治成了招待熟客的地方。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb26_27]],["left"]=[[fb26_26]],["name"]=[[侧厅]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb26_24]]},["fb26_28"]={["down"]=[[fb26_29]],["dsc"]=[[这里是后院。走到这里，花香味更加浓烈了。你仔细一看，东南边有一道圆形门，似乎花香是从那里传出来的。从这里再往南走，就是李员外的卧室了。]],["id"]=[[fb26_28]],["name"]=[[后院]],["permission"]=1,["rightDown"]=[[fb26_30]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_26]]},["fb26_29"]={["dsc"]=[[这里是李员外的卧室，卧室中央横拉着一道大帘子。在帘后有一张雕着八仙过海的大床，床头有一个抽屉。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb26_29]],["name"]=[[卧室]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb26_28]]},["fb26_30"]={["down"]=[[fb26_32]],["dsc"]=[[这里是一个小花园，杂乱地种着各种花草，看来无人打理，杂草已经长得很高了，有一些红的，白的鲜花夹杂在草丛中。东面有一道小门，南面是一座两层小楼。]],["id"]=[[fb26_30]],["leftUp"]=[[fb26_28]],["name"]=[[后花园]],["permission"]=1,["right"]=[[fb26_31]],["stepMusic"]=[[jiaobu]]},["fb26_31"]={["dsc"]=[[这是一片荒废了的花园，本来这里有一片小池塘，养着一些金鱼之类，现在池塘差不多也干涸了。池塘边立着一座假山，山上长满了青苔，看来已经很久没有人来过了。]],["id"]=[[fb26_31]],["left"]=[[fb26_30]],["name"]=[[后花园]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb26_32"]={["dsc"]=[[这里是一座两层的小楼，是建筑在庄园边缘用来登高凭拦看风景的。你轻轻靠在栏杆上，竟朽的吱吱作响。看来已经很久没有人有这个雅兴来这里看风景了。]],["id"]=[[fb26_32]],["name"]=[[观景楼]],["permission"]=1,["role1"]=[[fb26r32_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb26_30]]},["fb26_33"]={["dsc"]=[[往东一直走便是终南山了。]],["fightBackground"]=[[山外]],["id"]=[[fb26_33]],["left"]=[[fb26_07]],["name"]=[[终南山山道]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb26_34"]={["dsc"]=[[这是一条非常崎岖难行的山路，在此处可眺望终南山的景色，只见山险岭峻，山川毓秀，不少鸟ㄦ在枝头高声啼唱不绝。]],["fightBackground"]=[[山外]],["id"]=[[fb26_34]],["leftDown"]=[[fb26_07]],["name"]=[[狭窄山道]],["permission"]=1,["rightUp"]=[[fb26_35]],["stepMusic"]=[[jiaobu]]},["fb26_35"]={["dsc"]=[[山石雕筑的台阶，通往崇武楼。]],["id"]=[[fb26_35]],["leftDown"]=[[fb26_34]],["name"]=[[台阶]],["permission"]=1,["rightUp"]=[[fb26_36]],["stepMusic"]=[[jiaobu]]},["fb26_36"]={["dsc"]=[[崇武楼的大门，门口的两个石狮子甚是威武。]],["id"]=[[fb26_36]],["item1"]=[[bfitem3]],["item2"]=[[bfitem4]],["leftDown"]=[[fb26_35]],["name"]=[[崇武楼门]],["permission"]=1,["right"]=[[fb26_37]],["role1"]=[[fb26r36_1]],["stepMusic"]=[[jiaobu]]},["fb26_37"]={["dsc"]=[[空旷的房间，除了一张石床摆放在不起眼的角落，就再无任何装饰。]],["id"]=[[fb26_37]],["left"]=[[fb26_36]],["name"]=[[重石]],["permission"]=1,["rightUp"]=[[fb26_38]],["role1"]=[[fb26r37_1]],["stepMusic"]=[[jiaobu]]},["fb26_38"]={["dsc"]=[[楼身往上似乎越来越窄，楼梯也渐为挤仄。扶手上不少朽坏处续接了新木，漆色也是新旧不同。]],["id"]=[[fb26_38]],["leftDown"]=[[fb26_37]],["leftUp"]=[[fb26_39]],["name"]=[[阶梯]],["permission"]=1,["stepMusic"]=[